// Property definitions for the lead pipeline.
// Each returned item becomes one "create property" API call in the next node.

const opts = (pairs) =>
  pairs.map(([value, label], i) => ({ value, label, displayOrder: i }));

const contacts = [
  { name: "lead_score", label: "Lead score", type: "number", fieldType: "number" },
  { name: "lead_tier", label: "Lead tier", type: "enumeration", fieldType: "select",
    options: opts([["hot", "Hot"], ["warm", "Warm"], ["nurture", "Nurture"]]) },
  { name: "lead_score_reason", label: "Lead score reason", type: "string", fieldType: "textarea" },
  { name: "lead_utm_source", label: "Lead UTM source", type: "string", fieldType: "text" },
  { name: "lead_utm_medium", label: "Lead UTM medium", type: "string", fieldType: "text" },
  { name: "lead_utm_campaign", label: "Lead UTM campaign", type: "string", fieldType: "text" },
  { name: "is_free_email", label: "Is free email", type: "bool", fieldType: "booleancheckbox",
    options: opts([["true", "Yes"], ["false", "No"]]) },
  { name: "enrichment_status", label: "Enrichment status", type: "enumeration", fieldType: "select",
    options: opts([
      ["enriched_hunter", "Enriched (Hunter)"],
      ["enriched_website", "Enriched (website + LLM)"],
      ["skipped_free_email", "Skipped (free email)"],
      ["failed", "Failed"],
    ]) },
  { name: "lead_submission_id", label: "Lead submission ID", type: "string", fieldType: "text" },
];

const companies = [
  { name: "icp_segment", label: "ICP segment", type: "enumeration", fieldType: "select",
    options: opts([
      ["health_plan", "Health plan"],
      ["provider", "Provider"],
      ["employer", "Employer"],
      ["other", "Other"],
    ]) },
  { name: "enrichment_summary", label: "Enrichment summary", type: "string", fieldType: "textarea" },
];

const toItems = (objectType, props) =>
  props.map((p) => ({
    json: { objectType, body: { ...p, groupName: "lead_pipeline" } },
  }));

return [...toItems("contacts", contacts), ...toItems("companies", companies)];
